183			}
184		}
185		s.jobsMu.RUnlock()
186	
187		// Signal stop and wait for jobs to finish
188		close(s.stopCh)
189	
190		done := make(chan struct{})
191		go func() {
192			s.wg.Wait()
193			close(done)
194		}()
195	
196		select {
197		case <-done:
198			return nil
199		case <-ctx.Done():
200			return ctx.Err()
